import{_ as n,a as r}from"./chunks/reportverwaltung.BMspAEu6.js";import{_ as t,o as s,c as i,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const f=JSON.parse('{"title":"Reports erstellen und anpassen","description":"","frontmatter":{"title":"Reports erstellen und anpassen","source_pageid":1616,"source_revision":6810},"headers":[],"relativePath":"reporting/reportdesigner/reports-erstellen-anpassen-themenuebersicht.md","filePath":"reporting/reportdesigner/reports-erstellen-anpassen-themenuebersicht.md"}'),o={name:"reporting/reportdesigner/reports-erstellen-anpassen-themenuebersicht.md"};function l(p,e,d,u,g,h){return s(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="reports-erstellen-und-anpassen" tabindex="-1">Reports erstellen und anpassen <a class="header-anchor" href="#reports-erstellen-und-anpassen" aria-label="Permalink to &quot;Reports erstellen und anpassen&quot;">​</a></h1><p>Beginnen Sie mit einer vorhandenen Vorlage oder erstellen Sie einen neuen Report. Die folgenden Anleitungen erklären den Aufbau und führen durch die ersten Bearbeitungsschritte.</p><p><a href="/reporting/reportdesigner/reportdesigner-schnelleinstieg.html">Den passenden Einstieg in den Reportdesigner finden</a></p><h2 id="reports-erstellen-und-anpassen-1" tabindex="-1">Reports erstellen und anpassen <a class="header-anchor" href="#reports-erstellen-und-anpassen-1" aria-label="Permalink to &quot;Reports erstellen und anpassen&quot;">​</a></h2><p>Diese Seite bietet eine thematische Übersicht zu allen Artikeln, die beschreiben, wie Reports in SchILD-NRW 3 neu erstellt und vorhandene Reports abgeändert und erweitert werden können. Sie dient dazu, schnell den passenden Einstieg in die Erstellung oder Bearbeitung von Berichten zu finden.</p><h2 id="aufruf-und-funktionsweise-des-reportdesigners" tabindex="-1">Aufruf und Funktionsweise des Reportdesigners <a class="header-anchor" href="#aufruf-und-funktionsweise-des-reportdesigners" aria-label="Permalink to &quot;Aufruf und Funktionsweise des Reportdesigners&quot;">​</a></h2><p><a href="/bilder/reportdesigner/reportdesigner.png"><img src="'+n+'" alt="Der Reportdesigner" loading="lazy"></a></p><p><em>Der Reportdesigner</em></p><p>Mit dem <strong>Reportdesigner</strong> erstellen oder ändern Sie Reportvorlagen. Eine Vorlage legt fest, welche Daten ausgegeben werden und wie das Dokument aussieht. Die Ausgabe können Sie drucken, als PDF speichern oder per E-Mail versenden. Der Reportdesigner stammt von <a href="https://www.digital-metaphors.com" target="_blank" rel="noreferrer">Digital Metaphors</a> und ist in SchILD-NRW 3 eingebunden.</p><p><a href="/bilder/reportdesigner/reportverwaltung.png"><img src="'+r+'" alt="Die Reportverwaltung" loading="lazy"></a></p><p><em>Die Reportverwaltung</em></p><p>Eine Reportvorlage wird als Datei mit der Endung <code>.rtm</code> unter <code>SVWS-Arbeitsverzeichnis\\Schild-Reports\\</code> gespeichert. Die <strong>Reportverwaltung</strong> zeigt die dort verfügbaren Vorlagen an.</p><ul><li><strong>Vorhandene Vorlage bearbeiten:</strong> Klicken Sie mit der rechten Maustaste auf die RTM-Datei und wählen Sie <strong>Report bearbeiten</strong>.</li><li><strong>Neue Vorlage erstellen:</strong> Klicken Sie in der Reportverwaltung auf <strong>Neu</strong>.</li></ul><p>RTM-Dateien können im Reportordner ergänzt oder gelöscht werden.</p><h3 id="wie-funktioniert-ein-report" tabindex="-1">Wie funktioniert ein Report? <a class="header-anchor" href="#wie-funktioniert-ein-report" aria-label="Permalink to &quot;Wie funktioniert ein Report?&quot;">​</a></h3><ul><li><a href="/reporting/reportdesigner/was-leistet-ein-report-in-schild-nrw-3.html">Wie ein Report Daten zu einer Ausgabe zusammenführt</a></li></ul><p>Verstehen Sie, was ein Report ist und wie er funktioniert</p><h3 id="reports-erstellen-und-anpassen-2" tabindex="-1">Reports erstellen und anpassen <a class="header-anchor" href="#reports-erstellen-und-anpassen-2" aria-label="Permalink to &quot;Reports erstellen und anpassen&quot;">​</a></h3><ul><li><a href="/reporting/reportdesigner/neuen-report-erstellen.html">Einen Report ohne Assistenten erstellen</a></li></ul><p>Erstellen Sie einen ersten Report mit dem Reportdesigner</p><ul><li><a href="/reporting/reportdesigner/einen-vorhandenen-report-anpassen.html">Einen vorhandenen Report anpassen</a></li></ul><p>Vorhandene Vorlagen an die eigene Schule anpassen</p><ul><li><a href="/reporting/reportdesigner/einen-neuen-report-mit-dem-berichtsassistenten-erstellen.html">Einen Report mit dem Berichtsassistenten erstellen</a>´</li></ul><p>Ein Assistent unterstützt Sie bei der Erstellung einfacher Reports</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Reports_erstellen_%26_anpassen_Themen%C3%BCbersicht" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6810.</p>',26)])])}const R=t(o,[["render",l]]);export{f as __pageData,R as default};
